<template><section class="live-tile" :class="{selected,paused}" :aria-label="device.code+' '+device.label" @click="$emit('select',device.id)" @dblclick="$emit('fullscreen',device.id)">
  <header><strong :title="device.label">{{device.code}}</strong><span class="tile-state" :class="{online:hasFreshFrame&&!paused}"><i/>{{stateText}}</span><time>{{frameTime}}</time></header>
  <div class="tile-picture"><canvas ref="canvas" :aria-label="device.label+'实时视频'"/><div v-if="!hasFrame" class="tile-unavailable"><VideoOff :size="26" :stroke-width="1.3"/><strong>{{device.host?'等待视频连接':'尚未配置相机'}}</strong><span v-if="device.host" :title="device.runtime?.error||''">{{failure||device.runtime?.error||'等待摄像机返回画面'}}</span><button v-if="canConfigure" @click.stop="$emit('configure',device.id)">{{device.host?'检查连接':'配置相机'}}<ChevronRight :size="13"/></button></div><div v-else-if="!hasFreshFrame&&!paused" class="stale-frame"><LoaderCircle :size="21"/><span>视频中断，正在重连</span></div>
  <div class="tile-controls" @click.stop><span>{{paused?'画面已暂停':sizeText}}</span><button :disabled="!hasFrame||!canSnapshot" :title="!canSnapshot?'当前账号没有抓拍权限':!hasFrame?'等待视频画面':'保存当前帧'" :aria-label="'抓拍 '+device.code" @click="snapshot"><Camera :size="20"/></button><button :disabled="!hasFrame" :title="paused?'恢复实时画面':'暂停画面'" :aria-label="(paused?'恢复 ':'暂停 ')+device.code" @click="paused=!paused"><component :is="paused?Play:Pause" :size="19"/></button><button :aria-label="'全屏 '+device.code" title="全屏视频" @click="$emit('fullscreen',device.id)"><Maximize :size="19"/></button></div></div>
</section></template>
<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue';
import {VideoOff,Camera,Pause,Play,Maximize,ChevronRight,LoaderCircle} from 'lucide-vue-next';
import type {MonitorDevice} from '@/types/monitor';
const props=defineProps<{device:MonitorDevice;selected:boolean;canSnapshot:boolean;canConfigure:boolean}>();
const emit=defineEmits<{select:[id:string];fullscreen:[id:string];configure:[id:string];error:[message:string]}>();
const canvas=ref<HTMLCanvasElement|null>(null),paused=ref(false),hasFrame=ref(false),lastAt=ref(0),now=ref(Date.now()),failure=ref(''),frameTime=ref('—'),frameWidth=ref(0),frameHeight=ref(0);
let bitmap:ImageBitmap|null=null,observer:ResizeObserver|undefined,timer:ReturnType<typeof setInterval>|undefined;
const hasFreshFrame=computed(()=>hasFrame.value&&now.value-lastAt.value<4000);
const sizeText=computed(()=>frameWidth.value?frameWidth.value+' × '+frameHeight.value:'');
const stateText=computed(()=>paused.value?'暂停':hasFreshFrame.value?'实时':props.device.runtime?.state==='error'?'离线':props.device.host?'连接中':'未配置');
function draw(){const el=canvas.value;if(!el)return;const rect=el.getBoundingClientRect();if(rect.width<1||rect.height<1)return;const dpr=Math.min(devicePixelRatio||1,2);el.width=Math.round(rect.width*dpr);el.height=Math.round(rect.height*dpr);const ctx=el.getContext('2d');if(!ctx)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#202834';ctx.fillRect(0,0,rect.width,rect.height);if(bitmap){const factor=Math.min(rect.width/bitmap.width,rect.height/bitmap.height),w=bitmap.width*factor,h=bitmap.height*factor;ctx.drawImage(bitmap,(rect.width-w)/2,(rect.height-h)/2,w,h)}}
function presentFrame(next:ImageBitmap,receivedAt=Date.now()){if(paused.value){next.close();return}bitmap?.close();bitmap=next;frameWidth.value=next.width;frameHeight.value=next.height;now.value=Date.now();lastAt.value=Number.isFinite(receivedAt)&&receivedAt>1e11?Math.min(receivedAt,now.value):now.value;frameTime.value=new Date(lastAt.value).toLocaleTimeString('zh-CN',{hour12:false});hasFrame.value=true;failure.value='';draw()}
function clearFrame(){bitmap?.close();bitmap=null;hasFrame.value=false;paused.value=false;lastAt.value=0;frameTime.value='—';draw()}
function setFailure(message:string){failure.value=message}
async function snapshot(){if(!bitmap||!props.canSnapshot)return;try{const frame=document.createElement('canvas');frame.width=bitmap.width;frame.height=bitmap.height;frame.getContext('2d')!.drawImage(bitmap,0,0);const blob=await new Promise<Blob>((resolve,reject)=>frame.toBlob(value=>value?resolve(value):reject(new Error('抓拍生成失败')),'image/png'));const url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=props.device.code+'-'+new Date(lastAt.value).toISOString().replace(/[:.]/g,'-')+'.png';document.body.appendChild(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}catch(error){emit('error',(error as Error).message)}}
defineExpose({presentFrame,clearFrame,setFailure});
onMounted(()=>{observer=new ResizeObserver(draw);if(canvas.value)observer.observe(canvas.value);timer=setInterval(()=>now.value=Date.now(),500);draw()});
onUnmounted(()=>{observer?.disconnect();clearInterval(timer);bitmap?.close()});
</script>
<style scoped>
.live-tile{height:100%;min-height:0;display:flex;flex-direction:column;background:#202834;border:2px solid transparent;border-radius:9px;overflow:hidden;position:relative;cursor:pointer;transition:border-color .15s}.live-tile.selected{border-color:#0968ff}.live-tile>header{height:30px;min-height:30px;background:linear-gradient(100deg,#2d3543,#222a36);color:white;display:flex;gap:12px;align-items:center;padding:0 11px;font-size:14px;line-height:1;white-space:nowrap}.live-tile>header strong{font-size:16px;font-weight:650}.live-tile>header time{margin-left:auto;font-size:13px;font-variant-numeric:tabular-nums}.tile-state{display:flex;align-items:center;gap:7px;font-size:12px;color:#d6dfeb}.tile-state i{display:block;width:9px;height:9px;background:#8995a7;border-radius:50%}.tile-state.online i{background:#31df4f}.tile-picture{position:relative;flex:1;min-height:0}.tile-picture canvas{display:block;width:100%;height:100%}.tile-unavailable{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;color:#91a1b7;gap:8px;text-align:center;padding:16px;background:linear-gradient(145deg,#eaf0fa,#f4f7fc)}.tile-unavailable strong{font-size:14px;font-weight:500}.tile-unavailable>span{font-size:11px;max-width:95%;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;color:#8c9db4}.tile-unavailable>button{border:0;background:none;color:#0968ff;font-size:12px;display:flex;align-items:center;gap:2px;padding:5px}.stale-frame{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:10px;background:#18253499;color:#fff;font-size:13px;backdrop-filter:blur(2px)}.tile-controls{position:absolute;bottom:0;left:0;right:0;height:35px;padding:0 8px;display:flex;gap:12px;align-items:center;background:#202a39d9;color:white;opacity:0;transition:opacity .15s}.live-tile:hover .tile-controls,.live-tile.selected .tile-controls,.live-tile:focus-within .tile-controls,.live-tile.paused .tile-controls{opacity:1}.tile-controls>span{margin-right:auto;font-size:10px;color:#d3dde9;white-space:nowrap}.tile-controls>button{display:grid;place-items:center;padding:0;width:24px;height:28px;background:none;border:0;color:white}.tile-controls>button:hover{color:#86b8ff}.tile-controls>button:disabled{opacity:.3;cursor:not-allowed}.live-tile:fullscreen{border:0;border-radius:0}.live-tile:fullscreen>header{height:44px;min-height:44px}.live-tile:fullscreen .tile-controls{opacity:1;height:46px}
@container video-wall (max-width:600px){.live-tile>header{gap:5px;padding:0 6px}.live-tile>header time{font-size:10px}.tile-state{font-size:10px}.live-tile>header strong{font-size:13px}.tile-controls{gap:6px}.tile-controls>span{display:none}.tile-unavailable{padding:5px;gap:3px}.tile-unavailable strong{font-size:11px}.tile-unavailable>span{display:none}}
</style>
